struct Fixture{source:Temp,target:Temp,owner:Harness,workspace:PathBuf,id:String,choices:Choices}
impl Fixture{
 fn new()->Self{Self::with_authority(true)}
 fn with_authority(authority:bool)->Self{Self::with_history(authority,false)}
 fn with_history(authority:bool,old_goals:bool)->Self{
  let source=Temp::new();let layout=source.basic();let h=Harness::new();let active=Publication::begin(h.claim(&layout).unwrap(),layout).unwrap().publish().unwrap();let paths=active.paths().unwrap();
  let mut settings=crate::settings::Settings::default();settings.autostart=true;settings.cli_full_access=true;settings.phone_link=true;settings.phone_relay=true;settings.pet_system_center=true;settings.chat_provider="lmstudio".into();settings.chat_models.insert("lmstudio".into(),"explicit-free-fixture".into());settings.lmstudio_url="http://127.0.0.1:11444".into();
  fs::write(paths.config.join("settings.json"),serde_json::to_vec(&settings).unwrap()).unwrap();fs::write(paths.config.join("pets.json"),serde_json::to_vec(&crate::pet_config::defaults()).unwrap()).unwrap();
  source.file(&paths.config.join("sources.json"),br#"{"version":1,"generation":3,"sources":[{"id":"calendar","revision":1,"kind":"ics","name":"Fixture calendar","path":"/private-fixture/calendar.ics","enabled":true,"owners":[{"petId":"ai_lmstudio","conversationId":"old-current"}]}]}"#);
  source.file(&paths.data.join("Flow/prefs.json"),br#"{"enabled":true,"voice":true,"cleanup":true,"voiceOutput":"system"}"#);
  fs::write(paths.data.join("assistant/conversations.json"),br#"{"version":4,"pets":{"codex":{"id":"old-current","created":1,"updated":2,"messages":[{"role":"user","content":"original private fixture message"}],"session":{"id":"old-native","cwd":"/private-fixture","full_access":false},"tasks":[]}},"archives":{}}"#).unwrap();
  if old_goals{crate::pet_runtime::restoration::fixture_copied_goal_catalog(&paths.config.join("pet-runtime-v1"));source.file(&paths.data.join("inbox/independent-unknown.bin"),b"uncertain consumption remains unknown");}
  if authority{crate::pet_runtime::restoration::fixture_empty_authority(&paths.config.join("pet-runtime-consent-v1")).unwrap();}
  let workspace=source.0.join("backups");fs::DirBuilder::new().mode(0o700).create(&workspace).unwrap();let backup=current_profile::Review::capture(active,&workspace).unwrap();let hash=backup.fingerprint().unwrap();let(id,_)=backup.copy(&hash).unwrap();
  let target=Temp::new();let layout=target.layout();for path in [&layout.legacy_config,&layout.legacy_data]{fs::DirBuilder::new().recursive(true).mode(0o700).create(path).unwrap();}let owner=Harness::new();
  let review=Review::capture(owner.claim(&layout).unwrap(),layout.clone(),&workspace,&id,Mode::Fresh).unwrap();let hash=review.fingerprint().unwrap();review.apply(&hash).unwrap();
  if authority{let review=Review::capture(owner.claim(&layout).unwrap(),layout.clone(),&workspace,&id,Mode::Resume).unwrap().authority().unwrap();let hash=review.preview().unwrap()["fingerprint"].as_str().unwrap().to_owned();review.apply(&hash).unwrap();}
  let review=Review::capture(owner.claim(&layout).unwrap(),layout.clone(),&workspace,&id,Mode::Resume).unwrap().configuration().unwrap();let hash=review.preview().unwrap()["fingerprint"].as_str().unwrap().to_owned();review.apply(&hash).unwrap();let receipt=fs::read(layout.config().join(publication::restore::CONFIG_REVIEW)).unwrap();
  let choices=Choices{schema_version:1,inspection_receipt:hash_bytes(&receipt),main_pet:"ai_lmstudio".into(),active_pets:vec!["ai_lmstudio".into(),"agent_codex".into()],grants:vec![super::super::restored_projection::Grant{pet_id:"ai_lmstudio".into(),operations:vec![super::super::restored_projection::Operation::Music]}]};Self{source,target,owner,workspace,id,choices}
 }
 fn review(&self)->Result<Activation>{let layout=self.target.layout();Activation::capture(self.owner.claim(&layout)?,layout,&self.workspace,&self.id,self.choices.clone())}
 fn config(&self)->PathBuf{self.target.layout().config().to_owned()}
 fn admit(&self){let a=self.review().unwrap();let fp=a.preview().unwrap()["fingerprint"].as_str().unwrap().to_owned();a.apply(&fp).unwrap();}
 fn active(&self)->Result<Active>{let layout=self.target.layout();Active::open(self.owner.claim(&layout)?,layout)}
}
fn hash_bytes(b:&[u8])->String{hash(b)}
#[test]fn reviewed_operational_admission_retains_originals_loads_real_history_and_suspends_unreviewed_features(){
 let f=Fixture::new();let original=fs::read(f.config().join(publication::PAYLOAD).join("settings.json")).unwrap();let review=f.review().unwrap();let view=review.preview().unwrap();assert!(!f.config().join(JOB).exists());assert_eq!(view["executionAuthorityGranted"],false);assert_eq!(review.apply(&"0".repeat(64)).unwrap_err().error,Error::SourceChanged);assert!(!f.config().join(JOB).exists());f.admit();
 assert_eq!(fs::read(f.config().join(JOB).join("originals/config/settings.json")).unwrap(),original);let settings=crate::settings::read_initialized(&f.config().join(publication::PAYLOAD).join("settings.json")).unwrap();assert!(!settings.autostart&&!settings.cli_full_access&&!settings.phone_link&&!settings.phone_relay&&!settings.pet_system_center);assert_eq!(settings.chat_models["lmstudio"],"explicit-free-fixture");assert_eq!(settings.lmstudio_url,"http://127.0.0.1:11444");assert_eq!(settings.main_pill,"ai_lmstudio");assert_eq!(settings.chat_provider,"lmstudio");assert!(settings.shortcuts.values().all(|b|!b.enabled));
 let pets:Value=serde_json::from_slice(&fs::read(f.config().join(publication::PAYLOAD).join("pets.json")).unwrap()).unwrap();assert_eq!(pets["pets"]["ai_lmstudio"]["permissions"]["music"],true);assert_eq!(pets["pets"]["agent_codex"]["permissions"]["music"],false);let sources:Value=serde_json::from_slice(&fs::read(f.config().join(publication::PAYLOAD).join("sources.json")).unwrap()).unwrap();assert_eq!(sources["sources"][0]["enabled"],false);assert_eq!(sources["generation"],4);let flow:Value=serde_json::from_slice(&fs::read(f.target.layout().data().join(publication::PAYLOAD).join("Flow/prefs.json")).unwrap()).unwrap();assert_eq!(flow["voice"],false);assert_eq!(flow["cleanup"],false);
 let storage=f.active().unwrap().into_storage().unwrap();let h=storage.restored_history().unwrap().unwrap();assert!(h.conversation_allowed("codex","old-current",None).is_err());assert!(h.native_session_allowed("codex","old-native").is_err());assert!(h.conversation_allowed("codex","fresh-current",Some("fresh-native")).is_ok());assert!(storage.feature_pending("voice").unwrap());assert!(!storage.feature_pending("deterministicTask").unwrap());storage.current().unwrap();assert!(f.config().join(JOB).join(OPENED).exists());
}
#[test]fn each_durable_boundary_resumes_with_new_exact_review_without_reactivating_authority(){
 for checkpoint in [Step::OriginalsReady,Step::BeforeChange(0),Step::Staged(0),Step::Changed(0),Step::BeforeAdmission]{let f=Fixture::new();let review=f.review().unwrap();let fp=review.fingerprint.clone();let failed=review.apply_using(&fp,|s|if s==checkpoint{Err(Error::Unavailable)}else{Ok(())}).unwrap_err();assert_eq!(failed.error,Error::Unavailable,"{checkpoint:?}");assert!(f.active().is_err());let resumed=f.review().unwrap();assert_ne!(resumed.fingerprint,fp);let fresh=resumed.fingerprint.clone();resumed.apply(&fresh).unwrap();f.active().unwrap().into_storage().unwrap().current().unwrap();}
}
