#[test]fn completed_originals_are_not_reconstructed_and_foreign_or_tampered_payload_is_retained(){
 for mutation in ["original","payload","root","temp"]{let f=Fixture::new();let a=f.review().unwrap();let first=a.manifest.changes[0].clone();let fp=a.fingerprint.clone();a.apply_using(&fp,|s|if s==Step::OriginalsReady{Err(Error::Unavailable)}else{Ok(())}).unwrap_err();let damaged=match mutation{"original"=>f.config().join(JOB).join("originals/config/settings.json"),"root"=>f.config().join(publication::COMPLETE),"temp"=>f.config().join(publication::PAYLOAD).join(first.temp),_=>f.config().join(publication::PAYLOAD).join("settings.json")};if mutation=="original"{fs::remove_file(&damaged).unwrap();}else if mutation=="temp"{f.target.file(&damaged,b"foreign bytes");}else{fs::write(&damaged,b"foreign bytes").unwrap();}if let Ok(a)=f.review(){let fp=a.fingerprint.clone();assert!(a.apply(&fp).is_err());}assert!(!f.config().join(publication::ADMITTED).exists());if mutation=="original"{assert!(!damaged.exists());}else{assert_eq!(fs::read(damaged).unwrap(),b"foreign bytes");}}
}
#[test]fn ownership_loss_before_transform_or_admission_prevents_later_effects(){
 for checkpoint in [Step::OriginalsReady,Step::Staged(0),Step::BeforeAdmission]{let f=Fixture::new();let a=f.review().unwrap();let fp=a.fingerprint.clone();let failure=a.apply_using(&fp,|s|{if s==checkpoint{f.owner.release();}Ok(())}).unwrap_err();assert_eq!(failure.error,Error::OwnershipLost);assert!(!f.config().join(publication::ADMITTED).exists());}
}
