fn portable_workspace(f:&Fixture)->PathBuf{let p=f.target.0.join("portable-backups");fs::DirBuilder::new().mode(0o700).create(&p).unwrap();p}
fn portable(f:&Fixture,workspace:&Path)->String{let a=f.active().unwrap();let r=current_profile::Review::capture(a,workspace).unwrap();let fp=r.fingerprint().unwrap();r.copy(&fp).unwrap().0}
#[test]fn portable_root2_captures_current_work_and_all_recovery_metadata_without_needing_original_location(){
 let f=Fixture::new();f.admit();let storage=f.active().unwrap().into_storage().unwrap();let paths=storage.paths().unwrap();f.target.file(&paths.config.join("pet-runtime-results-v1/unknown.json"),br#"{"possibleEffect":true,"newBudgetObserved":2,"unknownConsumption":1}"#);f.target.file(&paths.data.join("assistant/restored-new-draft.bin"),b"new private draft after restoration");drop(storage);
 let workspace=portable_workspace(&f);let review=current_profile::Review::capture(f.active().unwrap(),&workspace).unwrap();let view=review.preview().unwrap();assert_eq!(view["archiveVersion"],2);assert_eq!(view["includesRecoveryMetadata"],true);assert_eq!(view["scope"],"entireAdmittedRootPairWithRecoveryMetadata");assert_eq!(view["executionAuthorityGranted"],false);assert_eq!(fs::read_dir(&workspace).unwrap().count(),0);let fp=review.fingerprint().unwrap();let(id,_)=review.copy(&fp).unwrap();let archive=workspace.join(format!("current-profile-{id}"));
 for name in [publication::ADMITTED,publication::HEADER,publication::COMPLETE,".restore-activation/manifest.json",".restore-activation/history.json",".restore-activation/sealed.json",".restore-activation/opened.json",".restore-activation/originals/config/settings.json","payload/pet-runtime-consent-v1/.restored-history.json","payload/pet-runtime-results-v1/unknown.json"]{assert_eq!(fs::read(archive.join("config").join(name)).unwrap(),fs::read(f.config().join(name)).unwrap(),"{name}");}
 assert_eq!(fs::read(archive.join("data/payload/assistant/restored-new-draft.bin")).unwrap(),b"new private draft after restoration");let manifest:Value=serde_json::from_slice(&fs::read(archive.join("manifest.json")).unwrap()).unwrap();assert_eq!(manifest["version"],2);assert_eq!(manifest["origin"]["schemaVersion"],2);
 fs::rename(f.config(),f.target.0.join("source-config-offline")).unwrap();fs::rename(f.target.layout().data(),f.target.0.join("source-data-offline")).unwrap();let inspection=staging::inspect_current(&workspace,&id).unwrap();assert_eq!(inspection.phase,staging::Phase::VerifiedData);assert_eq!(inspection.archive_version,2);assert!(inspection.includes_recovery_metadata);assert!(staging::CurrentArchive::open(&workspace,&id).is_err());let response=crate::pet_data::backup_cli::execute(crate::pet_data::backup_cli::Request::Inspect{workspace,id},"","no-native-authority",f.target.layout()).unwrap();assert_eq!(response["archiveVersion"],2);assert_eq!(response["dataRestorationAvailable"],true);assert_eq!(response["runtimeActivationAvailable"],false);assert_eq!(response["explicitReviewRequired"],true);assert_eq!(response["executionAuthorityGranted"],false);
}
